//! Red tests for the VT fuzz findings (fuzz catalog row e, vt_resize_fuzz).
//! Measurement only: each test fails on the base and passes when the
//! finding is fixed. Repros: /work/wt/chrome-parity-design/fuzz-findings/terminal/.
//!
//! The oracle is the fuzzer's REPLAY check: a fresh terminal of the same
//! size fed `vt_replay_bytes()` (the attach primitive) must show the same
//! viewport text and cursor as the terminal.

use ghostty_vt::{Callbacks, SnapshotPhase, Terminal, reencode_ready};

const SCROLLBACK: usize = 1 << 20;

enum Op {
    Write(&'static [u8]),
    Resize(u16, u16),
}

/// The first REPLAY difference after any op, or `None`.
fn replay_difference(start: (u16, u16), ops: &[Op]) -> Option<String> {
    let mut term = Terminal::new(start.0, start.1, SCROLLBACK, Callbacks::default()).unwrap();
    for (index, op) in ops.iter().enumerate() {
        match op {
            Op::Write(bytes) => term.vt_write(bytes),
            Op::Resize(cols, rows) => term.resize(*cols, *rows, 8, 16).unwrap(),
        }
        if !term.vt_stream_is_ground() {
            continue;
        }
        let replay = term.vt_replay_bytes().unwrap();
        let mut view =
            Terminal::new(term.cols(), term.rows(), SCROLLBACK, Callbacks::default()).unwrap();
        view.vt_write(&replay);
        let (text, view_text) = (term.viewport_text().unwrap(), view.viewport_text().unwrap());
        if text != view_text || term.cursor_position() != view.cursor_position() {
            return Some(format!(
                "step {index} at {}x{}:\n terminal {text:?} cursor {:?}\n view     {view_text:?} cursor {:?}",
                term.cols(),
                term.rows(),
                term.cursor_position(),
                view.cursor_position()
            ));
        }
    }
    None
}

/// E1 (job 5a763be1e029d3dfff9c4001, proptest minimal input): a 21-cell
/// line soft-wraps at 20 columns, then the program turns autowrap off
/// (DECAWM, CSI ? 7 l). The replay redraws the row with autowrap already
/// off, so its last cell overwrites column 20 and the wrapped "a" is lost:
/// the view shows "00 0A0a  0A0AA AaAAa" for "00 0A0a  0A0AA AaAA0" + "a".
#[test]
fn e1_replay_keeps_a_soft_wrapped_row_when_autowrap_is_off() {
    let ops = [Op::Write(b"00 0A0a  0A0AA AaAA0a"), Op::Write(b"\x1b[?7l")];
    let difference = replay_difference((20, 5), &ops);
    assert!(difference.is_none(), "E1: {}", difference.unwrap_or_default());
}

