#[test]
fn e2_replay_matches_the_terminal_after_a_resize_and_a_scroll_region() {
    let difference = replay_difference((20, 5), &e2_ops());
    assert!(difference.is_none(), "E2: {}", difference.unwrap_or_default());
}

/// Delta debugging (ddmin) of E2 to its smallest byte stream: one atom per
/// byte, resizes kept as atoms. Fails with the minimal stream while E2 is
/// red, so its log is the shrunk repro.
#[test]
fn e2_shrink() {
    #[derive(Clone, Copy)]
    enum Atom {
        Byte(u8),
        Resize(u16, u16),
    }
    let mut atoms = Vec::new();
    for op in e2_ops() {
        match op {
            Op::Write(bytes) => atoms.extend(bytes.iter().map(|byte| Atom::Byte(*byte))),
            Op::Resize(cols, rows) => atoms.push(Atom::Resize(cols, rows)),
        }
    }
    let fails = |atoms: &[Atom]| {
        let mut ops = Vec::new();
        let mut run = Vec::new();
        for atom in atoms {
            match atom {
                Atom::Byte(byte) => run.push(*byte),
                Atom::Resize(cols, rows) => {
                    if !run.is_empty() {
                        ops.push(Op::Write(Box::leak(std::mem::take(&mut run).into_boxed_slice())));
                    }
                    ops.push(Op::Resize(*cols, *rows));
                }
            }
        }
        if !run.is_empty() {
            ops.push(Op::Write(Box::leak(run.into_boxed_slice())));
        }
        replay_difference((20, 5), &ops).is_some()
    };
    if !fails(&atoms) {
        return;
    }
    let mut granularity = 2usize;
    while atoms.len() >= 2 {
        let chunk = atoms.len().div_ceil(granularity);
        let mut reduced = false;
        for start in (0..atoms.len()).step_by(chunk) {
            let mut candidate = atoms[..start].to_vec();
            candidate.extend_from_slice(&atoms[(start + chunk).min(atoms.len())..]);
            if fails(&candidate) {
                atoms = candidate;
                granularity = (granularity - 1).max(2);
                reduced = true;
                break;
            }
        }
        if !reduced {
            if granularity >= atoms.len() {
                break;
            }
            granularity = (granularity * 2).min(atoms.len());
        }
    }
    let mut shown = String::new();
    for atom in &atoms {
        match atom {
            Atom::Byte(byte) => shown.push_str(&std::ascii::escape_default(*byte).to_string()),
            Atom::Resize(cols, rows) => shown.push_str(&format!("<RESIZE {cols}x{rows}>")),
        }
    }
    panic!("E2 minimal stream ({} atoms) from 20x5: {shown}", atoms.len());
}

/// The snapshot path (`terminal-snapshot-v1`, what the macOS app uses when
/// its GHOSTSNP version matches the host's): a COMPLETE snapshot restored
/// into a fresh terminal must encode the same READY as the source. `None`
/// when they match after every op; else the first op where they differ.
fn snapshot_difference(start: (u16, u16), ops: &[Op]) -> Option<String> {
    let mut term = Terminal::new(start.0, start.1, SCROLLBACK, Callbacks::default()).unwrap();
    for (index, op) in ops.iter().enumerate() {
        match op {
            Op::Write(bytes) => term.vt_write(bytes),
            Op::Resize(cols, rows) => term.resize(*cols, *rows, 8, 16).unwrap(),
        }
        let ready = term.encode_snapshot(SnapshotPhase::Ready).unwrap();
        let complete = term.encode_snapshot(SnapshotPhase::Complete).unwrap();
        let restored = reencode_ready(&complete).unwrap();
        if restored != ready {
            return Some(format!(
                "step {index} at {}x{}: the restored READY ({} bytes) differs from the source READY ({} bytes)",
                term.cols(),
                term.rows(),
                restored.len(),
                ready.len()
            ));
        }
    }
    None
}

/// Probe: does E1 also break the snapshot path? Red here means the app's
/// GHOSTSNP attach has the fault too; green means only the byte replay has it.
#[test]
fn e1_snapshot_path_probe() {
    let ops = [Op::Write(b"00 0A0a  0A0AA AaAA0a"), Op::Write(b"\x1b[?7l")];
    let difference = snapshot_difference((20, 5), &ops);
    assert!(difference.is_none(), "E1 snapshot path: {}", difference.unwrap_or_default());
}

/// Probe: does E2 also break the snapshot path?
#[test]
fn e2_snapshot_path_probe() {
    let difference = snapshot_difference((20, 5), &e2_ops());
    assert!(difference.is_none(), "E2 snapshot path: {}", difference.unwrap_or_default());
}
